impl<B> Service<Request<B>> for Router<B>
where
    B: HttpBody + Send + 'static,
{
    type Response = Response;
    type Error = Infallible;
    type Future = RouteFuture<B, Infallible>;

    #[inline]
    fn poll_ready(&mut self, _: &mut Context<'_>) -> Poll<Result<(), Self::Error>> {
        Poll::Ready(Ok(()))
    }

    #[inline]
    fn call(&mut self, mut req: Request<B>) -> Self::Future {
        #[cfg(feature = "original-uri")]
        {
            use crate::extract::OriginalUri;

            if req.extensions().get::<OriginalUri>().is_none() {
                let original_uri = OriginalUri(req.uri().clone());
                req.extensions_mut().insert(original_uri);
            }
        }

        let path = req.uri().path().to_owned();
        let query = req.uri().query().map(ToOwned::to_owned);

        match self.node.at(&path) {
            Ok(match_) => {
                let id = *match_.value;

                #[cfg(feature = "matched-path")]
                if let Some(matched_path) = self.node.route_id_to_path.get(&id) {
                    use crate::extract::MatchedPath;

                    let matched_path =
                        if let Some(previous) = req.extensions_mut().get::<MatchedPath>() {
                            let previous = if let Some(previous) =
                                previous.as_str().strip_suffix(NEST_TAIL_PARAM_CAPTURE)
                            {
                                previous
                            } else {
                                previous.as_str()
                            };

                            let matched_path = format!("{}{}", previous, matched_path);
                            matched_path.into()
                        } else {
                            Arc::clone(matched_path)
                        };
                    req.extensions_mut().insert(MatchedPath(matched_path));
                } else {
                    #[cfg(debug_assertions)]
                    panic!("should always have a matched path for a route id");
                }

                {
                    let extensions = req.extensions_mut();
                    let current_params = extensions.get_mut();
                    if let Some(url_params::UrlParams::InvalidUtf8InPathParam { .. }) =
                        current_params
                    {
                    } else {
                        let mut decoded_params = Vec::new();
                        let mut invalid_key = None;
                        for (key, value) in match_.params.iter() {
                            if key.starts_with(NEST_TAIL_PARAM) {
                                continue;
                            }

                            match percent_encoding::percent_decode(value.as_bytes()).decode_utf8()
                            {
                                Ok(decoded) => {
                                    decoded_params.push((
                                        Arc::from(key),
                                        PercentDecodedStr(decoded.as_ref().into()),
                                    ));
                                }
                                Err(_) => {
                                    invalid_key = Some(Arc::from(key));
                                    break;
                                }
                            }
                        }

                        match (current_params, invalid_key, decoded_params) {
                            (
                                Some(url_params::UrlParams::InvalidUtf8InPathParam { .. }),
                                _,
                                _,
                            ) => {
                                unreachable!(
                                    "we check for this state earlier in this method"
                                )
                            }
                            (_, Some(invalid_key), _) => {
                                extensions.insert(
                                    url_params::UrlParams::InvalidUtf8InPathParam {
                                        key: invalid_key,
                                    },
                                );
                            }
                            (Some(url_params::UrlParams::Params(current)), None, params) => {
                                current.extend(params);
                            }
                            (None, None, params) => {
                                extensions.insert(url_params::UrlParams::Params(params));
                            }
                        }
                    }
                }

                let mut route = self
                    .routes
                    .get(&id)
                    .expect("no route for id. This is a bug in axum. Please file an issue")
                    .clone();

                match &mut route {
                    Endpoint::MethodRouter(inner) => inner.call(req),
                    Endpoint::Route(inner) => inner.call(req),
                }
            }
            Err(MatchError::NotFound) => match &self.fallback {
                Fallback::Default(inner) => inner.clone().call(req),
                Fallback::Custom(inner) => inner.clone().call(req),
            },
            Err(MatchError::MissingTrailingSlash) => {
                let mut fallback = match &self.fallback {
                    Fallback::Default(inner) => inner.clone(),
                    Fallback::Custom(inner) => inner.clone(),
                };

                let mut new_path_and_query = format!("{}/", &path);
                if let Some(query) = query.as_deref() {
                    new_path_and_query.push('?');
                    if query.contains('&') {
                        let mut first_pair = true;
                        for pair in query.split('&') {
                            if !first_pair {
                                new_path_and_query.push('&');
                            }
                            first_pair = false;
                            new_path_and_query.push_str(pair);
                        }
                    } else {
                        new_path_and_query.push_str(query);
                    }
                }

                let mut parts = req.uri().clone().into_parts();
                parts.path_and_query = Some(new_path_and_query.parse().unwrap());
                match Uri::from_parts(parts) {
                    Ok(new_uri) => {
                        let target = new_uri.to_string();
                        let location = HeaderValue::try_from(target.as_str())
                            .expect("URI isn't a valid header value");
                        let response = (
                            StatusCode::PERMANENT_REDIRECT,
                            [(LOCATION, location)],
                        )
                            .into_response();
                        RouteFuture::from_response(response)
                    }
                    Err(_) => fallback.call(req),
                }
            }
            Err(MatchError::ExtraTrailingSlash) => {
                let mut fallback = match &self.fallback {
                    Fallback::Default(inner) => inner.clone(),
                    Fallback::Custom(inner) => inner.clone(),
                };

                let stripped = path.strip_suffix('/').unwrap();
                let mut new_path_and_query = stripped.to_owned();
                if let Some(query) = query.as_deref() {
                    new_path_and_query.push('?');
                    if !query.is_empty() {
                        let mut offset = 0;
                        while offset < query.len() {
                            match query[offset..].find('&') {
                                Some(rel) => {
                                    new_path_and_query.push_str(&query[offset..offset + rel]);
                                    new_path_and_query.push('&');
                                    offset += rel + 1;
                                }
                                None => {
                                    new_path_and_query.push_str(&query[offset..]);
                                    break;
                                }
                            }
                        }
                    }
                }

                let mut parts = req.uri().clone().into_parts();
                parts.path_and_query = Some(new_path_and_query.parse().unwrap());
                match Uri::from_parts(parts) {
                    Ok(new_uri) => {
                        let target = new_uri.to_string();
                        RouteFuture::from_response(
                            Redirect::permanent(&target).into_response(),
                        )
                    }
                    Err(_) => fallback.call(req),
                }
            }
        }
    }
}

fn replace_path(uri: &Uri, new_path: &str) -> Option<Uri> {
    let mut new_path_and_query = new_path.to_owned();
    if let Some(query) = uri.query() {
        new_path_and_query.push('?');
        new_path_and_query.push_str(query);
    }

    let mut parts = uri.clone().into_parts();
    parts.path_and_query = Some(new_path_and_query.parse().unwrap());

    Uri::from_parts(parts).ok()
}

/// Wrapper around `matchit::Router` that supports merging two `Router`s.
#[derive(Clone, Default)]
struct Node {
    inner: matchit::Router<RouteId>,
    route_id_to_path: HashMap<RouteId, Arc<str>>,
    path_to_route_id: HashMap<Arc<str>, RouteId>,
}

impl Node {
    fn insert(
        &mut self,
        path: impl Into<String>,
        val: RouteId,
    ) -> Result<(), matchit::InsertError> {
        let path = path.into();

        self.inner.insert(&path, val)?;

        let shared_path: Arc<str> = path.into();
        self.route_id_to_path.insert(val, shared_path.clone());
        self.path_to_route_id.insert(shared_path, val);

        Ok(())
    }

    fn at<'n, 'p>(
        &'n self,
        path: &'p str,
    ) -> Result<matchit::Match<'n, 'p, &'n RouteId>, MatchError> {
        self.inner.at(path)
    }
}

impl fmt::Debug for Node {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("Node")
            .field("paths", &self.route_id_to_path)
            .finish()
    }
}

enum Fallback<B, E = Infallible> {
    Default(Route<B, E>),
    Custom(Route<B, E>),
}

impl<B, E> Clone for Fallback<B, E> {
    fn clone(&self) -> Self {
        match self {
            Fallback::Default(inner) => Fallback::Default(inner.clone()),

